const NEWS = [
 { date: 'November 18, 2026', title: 'Alireza Omidi presenting at MSL Seminar', summary: 'Alireza will be presenting at the MSL Seminar – Research Stories Mini-Symposium on Wednesday, November 18 at 3 pm PT. Alireza will present the new paper METALICA: METAdynamics and repLICA exchange for enhanced diffusion sampling. To attend in person, come to MSL room 102 (the MSL Lecture Theatre).', body: 'Alireza will be presenting at the MSL Seminar – Research Stories Mini-Symposium on Wednesday, November 18 at 3 pm PT. Alireza will present the new paper METALICA: METAdynamics and repLICA exchange for enhanced diffusion sampling. To attend in person, come to MSL room 102 (the MSL Lecture Theatre).', photo: '', caption: '', link: '' },
 { date: '2026', title: 'Anthropic x Adaptyv Protein Design Competition', summary: 'A group of lab members took on the Anthropic x Adaptyv protein design competition! Each target took us about two weeks, compared with about three months for designs in our own projects in the past. We submitted all our designs and are now waiting for the results. Hopefully some of ours get chosen!', body: 'A group of lab members took on the Anthropic x Adaptyv protein design competition! Our team: Juan Pablo Iglesias Ahualli, Alireza Omidi, Varun Sharma and Jasmine Wong, with Jörg Gsponer supervising.\nEach target in the competition took us about two weeks. Designs in one of our own projects in the past have taken about three months. Claude was a big help in speeding up and automating our processes. We submitted all the designs and are now waiting for the results. Anthropic and Adaptyv will use Adaptyv\'s automated labs to test around 5,000 designs for wet lab validation. Hopefully some of ours get chosen!', photo: 'img/news/competition-1.jpg\nimg/news/competition-2.jpg', caption: 'Photos from the Anthropic x Adaptyv protein design competition.', link: '' },
 { date: 'August 7, 2026', title: 'CIHR Grant Award', summary: 'A CIHR Project Grant led by Dr. Thibault Mayor, with Dr. Gsponer as co-investigator, will fund work on how the cell\'s quality-control machinery recognizes misfolded proteins carrying disease-causing mutations ($1,143,676 over five years).', body: 'Six Michael Smith Laboratories faculty are involved in projects funded through the Spring 2026 CIHR Project Grant competition, including Dr. Jörg Gsponer.\nThe Gsponer Lab project, "Molecular Principles Governing Degron Recognition in Misfolded Cytosolic Proteins with Pathological Missense Mutations", is led by Dr. Thibault Mayor with Dr. Gsponer as co-investigator. It is funded with $1,143,676 over five years.\nThe competition awarded about $412 million in research grants across Canada. At UBC, 51 projects received a total of $45.8 million in Project and Priority Announcement Grants.', photo: 'img/news/cihr-2026.jpg', caption: 'Top row, left to right: Drs. Thibault Mayor, Jörg Gsponer and Marco Marra. Bottom row: Drs. Xin Tang, Martin Hirst and Leonard Foster. Photo: Michael Smith Laboratories.', link: 'https://www.msl.ubc.ca/msl-faculty-spring-2026-cihr/' },
 { date: '2026', title: 'MoRFchibi 2.0 published', summary: 'Malhis and Gsponer present MoRFchibi 2.0, which outperforms existing predictors of protein-binding sites in disordered regions.', body: 'Malhis and Gsponer present MoRFchibi 2.0, which outperforms existing predictors of protein-binding sites in disordered regions.\nPaper: Malhis N, Gsponer J. Predicting molecular recognition features in protein sequences with MoRFchibi 2.0. BMC Bioinformatics (in press), 2026.', photo: '', caption: '', link: 'https://link.springer.com/article/10.1186/s12859-026-06532-x' },
 { date: '2026', title: 'Review in Cell Systems', summary: 'Omidi, Bui and Gsponer examine why dynamics and disorder remain a challenge for predicting protein interfaces in the age of AlphaFold.', body: 'Omidi, Bui and Gsponer examine why dynamics and disorder remain a challenge for predicting protein interfaces in the age of AlphaFold.\nPaper: Omidi A, Bui JA, Gsponer J. Predicting protein interfaces in the age of AlphaFold: Why dynamics and disorder remain a challenge. Cell Systems 17(1):101508, 2026.', photo: '', caption: '', link: 'https://www.cell.com/cell-systems/abstract/S2405-4712(25)00341-2' },
 { date: '2025', title: 'NSERC Discovery Grant', summary: 'Dr. Gsponer received a 2025 NSERC Discovery Grant.', body: 'Dr. Gsponer received a 2025 NSERC Discovery Grant.', photo: '', caption: '', link: '' },
 { date: '2025', title: 'AlphaFold and allosteric transitions', summary: 'Communications Chemistry paper testing AlphaFold on proteins with large-scale allosteric transitions.', body: 'Communications Chemistry paper testing AlphaFold on proteins with large-scale allosteric transitions.\nPaper: Perkins-Jechow BH, Iglesias Ahualli JP, Nhu TH, et al. Challenging AlphaFold in predicting proteins with large-scale allosteric transitions. Commun Chem 8(1):378, 2025.', photo: '', caption: '', link: 'https://www.nature.com/articles/s42004-025-01763-0' }
];
const SW = [
 { name: 'GraPES', summary: 'Granule Protein Enrichment Server. Predicts which proteins are constituents of biological condensates.', link: 'https://grapes.msl.ubc.ca', note: '', body: 'GraPES, the Granule Protein Enrichment Server, predicts whether a protein is likely to localize to cellular protein condensates, also called membraneless organelles. It is free to use and needs no registration.\nIt offers two predictors. MaGS (Membraneless organelle and Granule Score) is the more accurate one, based on experimental features, and looks proteins up in a precomputed database. MaGSeq is a sequence-based predictor for proteins that have no MaGS score or an unknown sequence; queries must be at least 150 amino acids.\nHow to use it: try MaGS first. If it gives no score, use MaGSeq. MaGSeq scores are not directly comparable with MaGS scores, so use it only when MaGS values are unavailable.\nScores are Z-scores. Suggested cutoffs for high, moderate and low:\nMaGS, human: above 1.16, 1.16 to 0.66, 0.66 to -0.36\nMaGS, yeast: above 1.08, 1.08 to 0.58, 0.58 to -0.39\nMaGSeq, human: above 0.90, 0.90 to 0.56, 0.56 to -0.33\nMaGSeq, yeast: above 0.89, 0.89 to 0.25, 0.25 to -0.45\nThe models were trained on stress granule proteins only. A high score means a protein can incorporate into a granule, not which type of condensate; that has to come from your own knowledge and experiments. Lowering the threshold raises sensitivity and raising it raises specificity.\nCite: Kuechler ER, Jacobson M, Mayor T, Gsponer J. GraPES: the Granule Protein Enrichment Server for prediction of biological condensate constituents. Nucleic Acids Res 50:W384-W391, 2022. Also: Kuechler ER, Budzyńska PM, Bernardini JP, Gsponer J, Mayor T. Distinct features of stress granule proteins predict localization in membraneless organelles. J Mol Biol 432(7):2349-2368, 2020.', links: 'GraPES web server: https://grapes.msl.ubc.ca\nMaGS, precomputed database: https://grapes.msl.ubc.ca/precomputed\nMaGSeq, sequence-based predictor: https://grapes.msl.ubc.ca/submit\nDocumentation: https://grapes.msl.ubc.ca/documentation\nSource code on GitHub: https://github.com/ekuec/2020_grapes_server\n2022 paper in Nucleic Acids Research: https://academic.oup.com/nar/advance-article/doi/10.1093/nar/gkac279/6574678\n2020 paper in J Mol Biol: https://doi.org/10.1016/j.jmb.2020.02.020', photo: '', caption: '' },
 { name: 'MoRFchibi', summary: 'Computational prediction of molecular recognition features (MoRFs) in protein sequences. Version 2.0 published 2026.', link: 'Open MoRFchibi 2.0: https://mc2.msl.ubc.ca/index.xhtml\nOpen original MoRFchibi: https://morf.msl.ubc.ca/index.xhtml', note: '', body: 'MoRFchibi predicts molecular recognition features (MoRFs): short segments within longer disordered protein regions that bind globular domains by switching from disorder to order. MoRFs play a role in signaling and regulation.\nMoRFchibi 2.0 (2025) uses an ensemble of four logistic-regression convolutional neural network models, trained on manually curated data collected in 2024. A reverse Bayes rule then normalizes for priors in the training data, so each score can be read on its own and combined with other scores that use the same output framework, such as IPA. It is significantly faster and more accurate than the earlier MoRFchibi predictors.\nHow to use it: run it on the web server, download the software from GitHub, or get the training and testing datasets from Zenodo.\nThe original MoRFchibi (2015) used SVM models trained on a high-throughput dataset collected in 2008. It has three predictors: MoRFchibi, for use as a component in other applications; MoRFchibi Light, for high-throughput prediction and most accurate for MoRFs longer than 30 residues; and MoRFchibi Web, for high-accuracy prediction. Light and Web ranked among the leading predictors in the first two rounds of CAID. A cutoff of about 0.725 is suggested for both.\nCite: Malhis N, Gsponer J. Predicting molecular recognition features in protein sequences with MoRFchibi 2.0. BMC Bioinformatics (in press), 2026; preprint on bioRxiv, 2025. For the original: Malhis N, Jacobson M, Gsponer J. MoRFchibi SYSTEM: software tools for the identification of MoRFs in protein sequences. Nucleic Acids Research, 2016.', links: 'MoRFchibi 2.0 web server: https://mc2.msl.ubc.ca/index.xhtml\nMoRFchibi 2.0 software on GitHub: https://github.com/NawarMalhis/MC2\nTraining and testing datasets on Zenodo: https://doi.org/10.5281/zenodo.20299225\n2.0 paper in BMC Bioinformatics: https://link.springer.com/article/10.1186/s12859-026-06532-x\n2.0 preprint on bioRxiv: https://www.biorxiv.org/content/10.1101/2025.01.31.635962v1.full\nOriginal MoRFchibi web server: https://morf.msl.ubc.ca/index.xhtml\nOriginal MoRFchibi paper in Nucleic Acids Research: http://nar.oxfordjournals.org/content/44/W1/W488.full', photo: '', caption: '' },
 { name: 'IDRBind', summary: 'Protein interface predictor for binding sites of intrinsically disordered regions, with a focus on MoRFs.', link: '', note: 'Retired', body: 'IDRBind is a protein interface predictor for the binding sites of intrinsically disordered protein regions, from short linear motifs to molecular recognition features (MoRFs). It focuses on MoRF-binding sites on the structures of folded proteins.\nIt uses residue composition, evolutionary conservation, relative accessible surface area, surface geometry, estimated B-factor and electrostatics.\nIDRBind is retired. Its web server, formerly at idrbind.msl.ubc.ca, is no longer available.\nCite: Wong ETC, Gsponer J. Predicting protein-protein interfaces that bind intrinsically disordered protein regions. J Mol Biol, 2019.', links: '', photo: '', caption: '' },
 { name: 'LIST', summary: 'Local Identity and Shared Taxa. Generates position conservation matrices for human protein sequences in FASTA format.', link: 'https://list-s2.msl.ubc.ca/', note: '', body: 'LIST (Local Identity and Shared Taxa) predicts how deleterious variants in protein sequences are, based on sequence similarity and shared taxa across genomes. A protein\'s contribution to a phenotype depends on proper folding, activity, localization and interactions, so both sequence and genome similarity matter when assessing a mutation.\nLIST scores range from 0 to 1, and higher scores mean more deleterious. A cutoff of 0.85 is suggested: at or above it is deleterious, below it is benign.\nLIST-S2 is the species-specific version and covers multiple species, including human. LIST is the human-only version, with precomputed predictions for individual Swiss-Prot human proteins. LIST-2 is licensed for academic and commercial use; the LIST source code is licensed for academic use only.\nHow to use it: submit jobs on the online web interface, download precomputed LIST-S2 predictions for multiple species, call the RESTful web server from a programming language, or build from the C++ source code.\nCite: Malhis N, Jacobson M, Jones SJM, Gsponer J. LIST-S2: taxonomy based sorting of deleterious missense mutations across species. Nucleic Acids Research, 2020. Also: Malhis N, Jones SJM, Gsponer J. Improved measures for evolutionary conservation that exploit taxonomy distances. Nature Communications 10(1):1556, 2019.', links: 'LIST-S2 web interface: https://list-s2.msl.ubc.ca/\nLIST-S2 precomputed predictions: https://precomputed.list-s2.msl.ubc.ca/\nLIST-S2 RESTful web server: https://list-s2-api.msl.ubc.ca/\nLIST-S2 source code on GitHub: https://github.com/NawarMalhis/LIST-S2\nLIST precomputed predictions: https://list.msl.ubc.ca/\nDownload all LIST predictions: https://doi.org/10.5683/SP2/BE6AEA\nLIST source code on GitHub, academic use only: https://github.com/NawarMalhis/LIST\nLIST-2 licence, academic and commercial: https://flintbox.com/public/project/51591/\nLIST-S2 paper in Nucleic Acids Research: https://doi.org/10.1093/nar/gkaa288\nPaper in Nature Communications: https://doi.org/10.1038/s41467-019-09583-2', photo: '', caption: '' },
 { name: 'MLnet', summary: 'Multi-layered network expansion model to identify common genetic modifiers across multiple diseases.', link: 'https://mlnet.lile.bio/', note: '', body: 'MLnet is a multi-layered network expansion model that aims to identify common genetic modifiers across multiple diseases.\nGenetic modifiers are genes or proteins that can lessen or worsen disease symptoms when their activity is raised or lowered, so they may be therapeutic targets.\nCite: Na D, Lim DH, Hong JS, et al. A multi-layered network expansion model identifies Akt1 as common modulator of neurodegeneration. Mol Syst Biol 19(12):e11801, 2023.', links: 'MLnet web server: https://mlnet.lile.bio/\nPaper in Molecular Systems Biology: https://www.embopress.org/doi/full/10.15252/msb.202311801', photo: '', caption: '' },
 { name: 'Cis-regPred', summary: 'A predictor of cis-regulatory elements.', link: 'http://cisregpred.lile.bio', note: '', body: 'Cis-regPred predicts cis-regulatory elements in proteins: intrinsically disordered regions that may regulate protein function by mediating interactions in cis. This on-site mechanism regulates protein domains in a steric or allosteric manner.\nCite: Yeon JH, et al. Systems-wide identification of cis-regulatory elements in proteins. Cell Systems 2(2):89-100, 2016.', links: 'Cis-regPred web server: http://cisregpred.lile.bio\nPaper in Cell Systems: https://www.cell.com/cell-systems/fulltext/S2405-4712(16)30034-5', photo: '', caption: '' },
 { name: 'Categorizer', summary: 'A tool for classifying genes into user-defined categories.', link: 'https://github.com/ubc-msl/categorizer', note: '', body: 'Categorizer (version 1.0) classifies genes into user-defined categories using Gene Ontology (GO) annotations and GO semantic similarity. It assigns genes to categories and calculates a p-value for the enrichment of each category. It is meant to avoid the redundant or overly specific lists of GO terms that typical GO enrichment tools produce.\nGenes can be assigned to the single best-scoring category, or to every category above a cutoff that you set.\nHow to use it: load a category file (three are provided: biological processes, enzyme classification and cellular localization), an annotation file, and a list of genes. A background gene list is optional and is needed for the enrichment analysis. Pick the single best category or multiple categories with a cutoff, then run. Results include category statistics, the categorization list and, with a background list, an enrichment graph of log10 p-values.\nPrecompiled Windows tools are available with and without a graphical interface (single core). The source code needs Python 2.7 or higher, Numpy, Scipy, matplotlib and wxPython. A Rebuild tool creates new GO similarity indexes for other datasets, such as UniProt annotations or human-only genes.\nCite: Categorizer, BMC Genomics 2014, 15:1091.\nContact: Dokyun Na (dna@ssbio.cau.ac.kr) or Jörg Gsponer (gsponer@msl.ubc.ca).', links: 'Categorizer on GitHub: https://github.com/ubc-msl/categorizer\nPaper in BMC Genomics: http://www.biomedcentral.com/1471-2164/15/1091/abstract\nMirror server in Asia: http://ssbio.cau.ac.kr/software/categorizer\nGO annotation files: http://www.geneontology.org/GO.downloads.annotations.shtml', photo: 'img/software/categorizer-main-window.png', caption: 'The Categorizer main window, from the original Categorizer page.' },
 { name: 'Easyworm', summary: 'Software to determine the mechanical properties of worm-like chains.', link: 'https://github.com/ubc-msl/easyworm', note: '', body: 'Easyworm is an open-source tool for analyzing the shape fluctuations of semi-flexible polymers. It measures their persistence lengths and, with additional tools, derives the Young\'s modulus.\nHow to use it: install the MATLAB Compiler Runtime (MCR) that matches the Easyworm build, get Easyworm from GitHub (source and binaries), and run the executable. The source code runs only inside MATLAB.\nEasyworm supports Windows 10 with MATLAB 2020a (MCR 2020a, 64-bit) and Linux64 with MATLAB 2012b (MCR 2012b, 64-bit).\nThe package includes example images of three polymer sets (two experimental, one synthetic) with persistence lengths of 52 nm, 1.5 µm and 100 µm, for testing and training. If your analysis of these sets does not give a similar persistence length, the analysis probably contains a mistake.\nImage files, such as .jpg or .tiff, must be in RGB color mode, even if they look grayscale, or they will not load properly. Grayscale-coded images, common in electron microscopy, can be converted to RGB in an image editor.\nCite: Lamour G, Kirkegaard JB, Li HB, Knowles TPJ, Gsponer J. Easyworm: an open-source software tool to determine the mechanical properties of worm-like chains. Source Code Biol Med 9:16, 2014.', links: 'Easyworm on GitHub: https://github.com/ubc-msl/easyworm\nPaper in Source Code for Biology and Medicine: http://www.scfbm.org/content/9/1/16\nMATLAB Runtime 2020a for Windows: https://ssd.mathworks.com/supportfiles/downloads/R2020a/Release/5/deployment_files/installer/complete/win64/MATLAB_Runtime_R2020a_Update_5_win64.zip\nMATLAB Runtime 2012b for Linux: https://ssd.mathworks.com/supportfiles/MCR_Runtime/R2012b/MCR_R2012b_glnxa64_installer.zip\nMathWorks MATLAB Runtime page: http://www.mathworks.com/products/compiler/mcr/', photo: 'img/software/easyworm-contours.jpg', caption: 'Example image from the original Easyworm page: overlaid polymer contours.' }
];
const DB = [
 { name: 'Mouse Interactome', summary: 'The mouse tissue interactome explorer, a project of the Foster and Gsponer laboratories at UBC. Based on an atlas of protein-protein interactions across mouse tissues.', link: 'https://tissue-interactomes.msl.ubc.ca', note: '', body: 'Mouse Interactome is a mouse tissue interactome explorer, a project of the Foster and Gsponer laboratories at UBC. It is based on an atlas of protein-protein interactions across mouse tissues.\nThe atlas maps the interactomes of seven mouse tissues with a quantitative proteomic approach that combines protein correlation profiling with stable isotope labeling of mammals (PCP-SILAM). The maps reveal more than 125,000 unique interactions, at a quality comparable to the highest-quality human screens, and give a proteome-scale view of how the interactome is rewired across mammalian tissues.\nThe study found a systematic suppression of cross-talk between the evolutionarily ancient housekeeping interactome and younger, tissue-specific modules. Rewired proteins are tightly regulated by several cellular mechanisms and are implicated in disease.\nCite: Skinnider MA, Scott NE, Prudova A, Kerr CH, Stoynov N, Stacey RG, Chan QWT, Rattray D, Gsponer J, Foster LJ. An atlas of protein-protein interactions across mouse tissues. Cell 184(15):4073-4089, 2021.', links: 'Mouse Interactome explorer: https://tissue-interactomes.msl.ubc.ca\nPaper in Cell: https://www.cell.com/cell/fulltext/S0092-8674(21)00704-2\nPaper on PubMed: https://pubmed.ncbi.nlm.nih.gov/34214469/', photo: '', caption: '' }
];
